import { ToolbarActionGroup } from "@fiftyone/components";
import { usePointSelection } from "./usePointSelection";
import { useMemo } from "react";
import { Icon, IconName } from "@voxel51/voodo";
import { useAgentSelector } from "./useAgentSelector";
import { useAnnotationAgent } from "./useAnnotationAgent";
import { InferenceCapability } from "../types";

/**
 * Hook which returns a {@link ToolbarActionGroup} encapsulating AI annotation
 * tooling.
 */
export const useAIAnnotationActionGroup = (): ToolbarActionGroup => {
  const pointSelection = usePointSelection();
  const { inferenceCapabilities } = useAnnotationAgent(
    useAgentSelector()?.activeAgent?.agent
  );

  return useMemo(
    () => ({
      id: "ai-annotation-tools",
      label: "AI Annotation",
      isHidden: false,
      actions: [
        {
          icon: <Icon name={IconName.AI} />,
          id: "ai-annotation-point-selection",
          isActive: pointSelection.isActive,
          isDisabled: ![
            InferenceCapability.POSITIVE_POINT,
            InferenceCapability.NEGATIVE_POINT,
          ].some((capability) => inferenceCapabilities.includes(capability)),
          isVisible: true,
          label: "AI Point Selection",
          onClick: () => {
            if (pointSelection.isActive) {
              pointSelection.deactivate();
            } else {
              pointSelection.activate();
            }
          },
          shortcut: "A",
          tooltip:
            "Select positive (inclusive) and negative (exclusive) points for segmentation",
        },
      ],
    }),
    [inferenceCapabilities, pointSelection]
  );
};

import {
  Align,
  Button,
  IconName,
  Justify,
  Size,
  Stack,
  Text,
  TextColor,
  TextVariant,
  Orientation,
  Spacing,
  Variant,
} from "@voxel51/voodo";
import React, { useCallback, useEffect, useState } from "react";
import { pluralizeSearches } from "../../utils";
import { BulkActionBarContainer } from "../styled";

type BulkActionBarProps = {
  selectedCount: number;
  onDelete: () => void;
  onCancel: () => void;
};

export default function BulkActionBar({
  selectedCount,
  onDelete,
  onCancel,
}: BulkActionBarProps) {
  const [confirming, setConfirming] = useState(false);

  // Reset confirmation state when selection is cleared
  useEffect(() => {
    if (selectedCount === 0) {
      setConfirming(false);
    }
  }, [selectedCount]);

  const handleDeleteClick = useCallback(() => {
    setConfirming(true);
  }, []);

  const handleConfirm = useCallback(() => {
    setConfirming(false);
    onDelete();
  }, [onDelete]);

  const handleCancelConfirm = useCallback(() => {
    setConfirming(false);
  }, []);

  if (selectedCount === 0) return null;

  const label = pluralizeSearches(selectedCount);

  return (
    <BulkActionBarContainer>
      {confirming ? (
        <Stack
          orientation={Orientation.Row}
          spacing={Spacing.Sm}
          align={Align.Center}
          justify={Justify.Between}
        >
          <Text variant={TextVariant.Md} color={TextColor.Destructive}>
            Delete {label}?
          </Text>
          <Stack orientation={Orientation.Row} spacing={Spacing.Sm}>
            <Button
              size={Size.Sm}
              variant={Variant.Secondary}
              onClick={handleCancelConfirm}
            >
              Cancel
            </Button>
            <Button
              size={Size.Sm}
              variant={Variant.Danger}
              leadingIcon={IconName.Delete}
              onClick={handleConfirm}
            >
              Confirm Delete
            </Button>
          </Stack>
        </Stack>
      ) : (
        <Stack
          orientation={Orientation.Row}
          spacing={Spacing.Sm}
          align={Align.Center}
          justify={Justify.Between}
        >
          <Text variant={TextVariant.Md} color={TextColor.Primary}>
            {label} selected
          </Text>
          <Stack orientation={Orientation.Row} spacing={Spacing.Sm}>
            <Button
              size={Size.Sm}
              variant={Variant.Secondary}
              onClick={onCancel}
            >
              Cancel
            </Button>
            <Button
              size={Size.Sm}
              variant={Variant.Danger}
              leadingIcon={IconName.Delete}
              onClick={handleDeleteClick}
            >
              Delete
            </Button>
          </Stack>
        </Stack>
      )}
    </BulkActionBarContainer>
  );
}

import {
  Align,
  Button,
  IconName,
  Orientation,
  Size,
  Spacing,
  Stack,
  Tooltip,
  Variant,
} from "@voxel51/voodo";
import React from "react";
import { QueryType, RunStatus, SimilarityRun } from "../../types";
import { tooltipTextStyle } from "../styled";

const tip = (text: string) => <span style={tooltipTextStyle}>{text}</span>;

/** Wrap a handler to stop propagation so card-level onClick doesn't fire. */
const stop =
  (fn: () => void): React.MouseEventHandler =>
  (e) => {
    e.stopPropagation();
    fn();
  };

type RunActionsProps = {
  run: SimilarityRun;
  isExpanded: boolean;
  onApply: (runId: string) => void;
  onClone: (runId: string) => void;
  onDelete: (runId: string) => void;
  onToggleExpand: (run: SimilarityRun) => void;
};

export default function RunActions({
  run,
  isExpanded,
  onApply,
  onClone,
  onDelete,
  onToggleExpand,
}: RunActionsProps) {
  const isImage = run.query_type === QueryType.Image && !run.patches_field;
  // Upload runs can't be cloned — the original image isn't persisted.
  const isUpload = run.query_type === QueryType.Upload;

  return (
    <Stack
      orientation={Orientation.Column}
      align={Align.End}
      spacing={Spacing.Xl}
    >
      <Stack>
        <Tooltip content={tip("Show results")}>
          <Button
            aria-label="Show results"
            size={Size.Md}
            variant={Variant.Borderless}
            leadingIcon={IconName.GridView}
            onClick={stop(() => onApply(run.run_id))}
            disabled={run.status !== RunStatus.Completed}
          />
        </Tooltip>
        <Tooltip
          content={tip(
            isUpload
              ? "Clone is not supported for file upload searches"
              : "Clone search"
          )}
        >
          {/* span wrapper lets the tooltip still fire on hover when the
              underlying button is disabled */}
          <span>
            <Button
              aria-label="Clone search"
              size={Size.Md}
              variant={Variant.Borderless}
              leadingIcon={IconName.ContentCopy}
              onClick={stop(() => onClone(run.run_id))}
              disabled={isUpload}
            />
